<?php
/** @var array<string, mixed> $attributes */
declare( strict_types=1 ); if ( ! defined( 'ABSPATH' ) ) { exit; } $nextsaas_items = nextsaas_items( $attributes, 'items' );
?>
<section <?php echo nextsaas_section_attrs( 'home-impact-features', $attributes, array( 'section', 'impact' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?>><div class="container"><div class="section-heading"><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><div class="heading-row"><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><p class="lead" data-nextsaas-rich="lead"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'lead' ) ); ?></p></div></div><div class="grid-3 impact-grid"><?php foreach ( $nextsaas_items as $nextsaas_i => $nextsaas_item ) : ?><article class="feature card-flat impact-card"><div class="impact-index"><span data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_i ); ?>.meta"><?php echo nextsaas_rich( (string) ( $nextsaas_item['meta'] ?? '' ) ); ?></span><?php echo nextsaas_icon( (string) ( $nextsaas_item['icon'] ?? '' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?></div><h3 data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_i ); ?>.heading"><?php echo nextsaas_rich( (string) ( $nextsaas_item['heading'] ?? '' ) ); ?></h3><p data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_i ); ?>.body"><?php echo nextsaas_rich( (string) ( $nextsaas_item['body'] ?? '' ) ); ?></p></article><?php endforeach; ?></div><p class="impact-note" data-nextsaas-rich="note"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'note' ) ); ?></p></div></section>
